#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long steps = 0;
    long long value = n;
    while (value != 1) {
        if (steps > 999999) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
        if (value > 1000000000000000LL) {
            puts("OVERFLOW_GUARD");
            return 0;
        }
        if (value & 1) {
            value = value * 3 + 1;
        } else {
            value >>= 1;
        }
        steps++;
    }
    printf("n=%lld steps=%lld\n", n, steps);
    return 0;
}
